      keywordsList: [{ word: "anxiety", translation: "xavotir, tashvish" }, { word: "army", translation: "armiya, qo'shin" }, { word: "billion", translation: "milliard" }, { word: "carve", translation: "o'ymoq, kesib shakl bermoq" }, { word: "consult", translation: "maslahatlashmoq" }, { word: "emergency", translation: "favqulodda vaziyat" }, { word: "fortune", translation: "omad, baxt" }, { word: "guarantee", translation: "kafolat bermoq" }, { word: "hike", translation: "piyoda sayr qilmoq (tog'da)" }, { word: "initial", translation: "boshlang'ich, birinchi" }, { word: "intense", translation: "kuchli, jiddiy" }, { word: "lend", translation: "qarzga bermoq, yordam qo'lini cho'zmoq" }, { word: "peak", translation: "cho'qqi" }, { word: "potential", translation: "ehtimoliy, potentsial" }, { word: "pride", translation: "g'urur, iftixor" }, { word: "proof", translation: "isbot, dalil" }, { word: "quit", translation: "to'xtatmoq, bas qilmoq" }, { word: "spin", translation: "aylanmoq, gir-gir aylanmoq" }, { word: "tiny", translation: "juda kichik, kichkina" }, { word: "tutor", translation: "repetitor, shaxsiy o'qituvchi" }],
